#!/usr/bin/env node
// GENERATED by Whetstone's emitter from .sdd/triage-rules.md (strict tier).
// Do NOT edit by hand — regenerate after changing triage-rules.md (ADR-0002).
// Non-blocking: it WARNS via additionalContext, never blocks the edit.
import fs from "node:fs";

// Strict-tier paths for THIS project, compiled from triage-rules.md.
// (For a different project the emitter bakes in that project's strict globs, e.g. src/sync/**.)
const STRICT_PREFIXES = [
  ".sdd/skills/", // skills copied verbatim into every bootstrapped project
  "SPEC.md", // schemas: signal / ADR / adapter / directory contract
  "init.md", // the emitter / compiler logic
];

let input;
try {
  input = JSON.parse(fs.readFileSync(0, "utf-8"));
} catch {
  process.exit(0); // never break the tool on a hook error
}

const fp = input?.tool_input?.file_path ?? "";
const projectDir = process.env.CLAUDE_PROJECT_DIR ?? input?.cwd ?? "";
const rel = projectDir && fp.startsWith(projectDir) ? fp.slice(projectDir.length + 1) : fp;

const hit = STRICT_PREFIXES.some((p) => rel === p || rel.startsWith(p));
if (hit) {
  console.log(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "defer",
        additionalContext:
          `⚠ strict-tier edit (${rel}). Per .sdd/triage-rules.md this propagates to every ` +
          `bootstrapped project: full TDD once code exists, plus fresh-context review and a ` +
          `worked example before it ships. Proceed deliberately.`,
      },
    })
  );
}
process.exit(0);
